insert into bridging.questions
select * from jsonb_populate_recordset(null::bridging.questions, $seed$[{"id":"01a00459-8de2-79fc-b442-a88cd6ce2f45","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"Benjamin and Daniel have monthly allowances in the ratio 7 : 4. After each of them spends $50, the ratio of their remaining allowances becomes 5 : 2. Calculate Daniel's allowance at the start.","model_answer":"$100","explanation":"Let Benjamin's initial allowance be 7x and Daniel's initial allowance be 4x. After spending $50 each, their remaining allowances are 7x - 50 and 4x - 50. Set up ratio: (7x - 50) / (4x - 50) = 5 / 2. Cross-multiply: 2(7x - 50) = 5(4x - 50) => 14x - 100 = 20x - 250 => 6x = 150 => x = 25. Daniel's allowance = 4 * 25 = $100.","difficulty":"Medium","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:36:13.026Z","updated_at":"2026-08-15T07:36:13.026Z"},{"id":"01a00459-8de7-7fc8-a4cc-433f7eecc779","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Given that 1 / (3^(k + 2)) = 3^4 + 3^4 + 3^4, find the value of k.","model_answer":"-7","explanation":"Simplify RHS: 3^4 + 3^4 + 3^4 = 3 * (3^4) = 3^5. Rewrite LHS using negative index: 1 / (3^(k + 2)) = 3^(-(k + 2)). Equating exponents: -(k + 2) = 5 => -k - 2 = 5 => -k = 7 => k = -7.","difficulty":"Medium","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:36:13.031Z","updated_at":"2026-08-15T07:36:13.031Z"},{"id":"01a00466-c83d-7730-85f3-8f230ac0d1fa","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Calculate √((15.2²)/(1 - 0.046)), giving your answer correct to the nearest whole number.","model_answer":"16","explanation":"Evaluate √((15.2²)/(0.954)) = 15.56... Therefore, the answer to the nearest whole number is 16.","difficulty":"Easy","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:39.931Z","updated_at":"2026-08-15T07:50:39.931Z"},{"id":"01a00466-c84e-7730-b6f3-4e8b47ddcba5","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Simplify 4x - 7(x - 2).","model_answer":"14 - 3x","explanation":"4x - 7(x - 2) = 4x - 7x + 14 = 14 - 3x.","difficulty":"Easy","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:39.950Z","updated_at":"2026-08-15T07:50:39.950Z"},{"id":"01a00466-c868-7374-a22f-9dbc4041ab71","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Simplify (18a²b⁴) ÷ (6ab⁻²), leaving your answer with positive indices.","model_answer":"3ab⁶","explanation":"(18a²b⁴)/(6ab⁻²) = 3a^(2-1)b^(4-(-2)) = 3ab⁶.","difficulty":"Easy","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:39.976Z","updated_at":"2026-08-15T07:50:39.976Z"},{"id":"01a00466-c877-7805-8381-a6648746bdb1","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"A car travels an average of 0.082 kilometres per litre of fuel. Find its fuel consumption in litres per kilometre, correct to three significant figures.","model_answer":"12.2 litres per kilometre","explanation":"Litres per kilometre = 1 ÷ 0.082 = 12.195..., which is 12.2 litres per kilometre to three significant figures.","difficulty":"Easy","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:39.991Z","updated_at":"2026-08-15T07:50:39.991Z"},{"id":"01a00466-c888-780d-8a37-ac9d34d7d95d","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Express 0.000736 in standard form.","model_answer":"7.36 × 10⁻⁴","explanation":"Move the decimal point four places to the right: 0.000736 = 7.36 × 10⁻⁴.","difficulty":"Easy","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.008Z","updated_at":"2026-08-15T07:50:40.008Z"},{"id":"01a00466-c899-730e-9715-0fd9006900ce","topic_id":"019f9df7-a2a2-78fc-bd9e-a40e9b4f9363","prompt":"Convert 0.00425 m³ into cm³.","model_answer":"4250 cm³","explanation":"Since 1 m³ = 1,000,000 cm³, 0.00425 m³ = 0.00425 × 1,000,000 = 4250 cm³.","difficulty":"Easy","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.025Z","updated_at":"2026-08-15T07:50:40.025Z"},{"id":"01a00466-c8ad-75d4-975b-4ffb2d5f4e49","topic_id":"019f9df7-a2a2-7877-afdf-c436930f3059","prompt":"Solve x/8 - (3x - 2)/5 = 2.","model_answer":"x = -64/19","explanation":"Multiply by 40: 5x - 8(3x - 2) = 80. Hence, 5x - 24x + 16 = 80, so -19x = 64 and x = -64/19.","difficulty":"Medium","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.045Z","updated_at":"2026-08-15T07:50:40.045Z"},{"id":"01a00466-c8b8-7337-9546-9dd3c5332c75","topic_id":"019f9df7-a2a2-78fc-bd9e-a40e9b4f9363","prompt":"A rectangular prism is made using 432 unit cubes. Its square base has side length greater than 3 units. Find the smallest possible height of the prism.","model_answer":"3 units","explanation":"If the square base side is s, then s²h = 432. Possible square factors of 432 with s > 3 are 16 (s=4, h=27), 36 (s=6, h=12), and 144 (s=12, h=3). The largest base area 144 yields the smallest height of 3 units.","difficulty":"Medium","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.056Z","updated_at":"2026-08-15T07:50:40.056Z"},{"id":"01a00466-c8d5-7640-8b59-e05d2de930e3","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"A laptop has a marked price of $m and is sold at a discount of d%. Express its selling price as a single fraction in terms of m and d.","model_answer":"m(100 - d)/100","explanation":"The discount is md/100. Selling price = m - md/100 = m(100 - d)/100.","difficulty":"Easy","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.085Z","updated_at":"2026-08-15T07:50:40.085Z"},{"id":"01a00466-c8e9-7526-a202-f1e78caca88b","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"A shop sells an item at the discounted price m(100 - d)/100 and makes a profit of 25%. Express the cost price as a single fraction in terms of m and d.","model_answer":"4m(100 - d)/500","explanation":"Selling price = 1.25 × cost price. Therefore, cost price = [m(100 - d)/100] ÷ 1.25 = 4m(100 - d)/500.","difficulty":"Medium","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.105Z","updated_at":"2026-08-15T07:50:40.105Z"},{"id":"01a00466-c8f3-7aaf-aa86-7fce1777f966","topic_id":"019f9df7-a2a2-7930-a717-cd252273c91f","prompt":"A bar chart compares monthly sales, but its vertical axis begins at $1500 instead of $0. Explain how this could mislead readers.","model_answer":"It exaggerates visible bar differences, making small variations appear much larger.","explanation":"Starting the vertical axis above zero removes the baseline and exaggerates the visible heights of the bars. Readers may therefore overestimate the differences between months.","difficulty":"Easy","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.115Z","updated_at":"2026-08-15T07:50:40.115Z"},{"id":"01a00466-c911-7720-9bd3-e464de4c4e5e","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Express 360 as a product of its prime factors.","model_answer":"2³ × 3² × 5","explanation":"360 = 36 × 10 = (2² × 3²)(2 × 5) = 2³ × 3² × 5.","difficulty":"Easy","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.145Z","updated_at":"2026-08-15T07:50:40.145Z"},{"id":"01a00466-c91b-7e98-af40-d3a0a6c9daf3","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Two integers have HCF 18 and LCM 360. Both integers are greater than 40. Find the two integers.","model_answer":"72 and 90","explanation":"Let the numbers be 18a and 18b, where a and b are coprime. Since their product is HCF × LCM = 18 × 360, ab = 20. The coprime factor pair giving numbers > 40 is a = 4 and b = 5, giving 72 and 90.","difficulty":"Medium","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.155Z","updated_at":"2026-08-15T07:50:40.155Z"},{"id":"01a00466-c926-78ed-9ecc-ea079d01fd5d","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"The force F between two objects is inversely proportional to the square of their separation d. If the separation is increased by 80%, calculate the percentage decrease in F.","model_answer":"69.1%","explanation":"The new distance is 1.8d. Hence, the new force is F/(1.8²) = F/3.24 ≈ 0.3086F. Percentage decrease = (1 - 0.3086) × 100% ≈ 69.1%.","difficulty":"Medium","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.166Z","updated_at":"2026-08-15T07:50:40.166Z"},{"id":"01a00466-c930-79ea-892b-14f1a6153c6c","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"The expression 6 - 8x - x² can be written in the form k - (x - h)². Find h and k, and state the maximum value of the expression.","model_answer":"h = -4, k = 22, maximum value = 22","explanation":"6 - 8x - x² = 6 - (x² + 8x + 16) + 16 = 22 - (x + 4)². Thus h = -4 and k = 22. Maximum value is 22 when x = -4.","difficulty":"Medium","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.176Z","updated_at":"2026-08-15T07:50:40.176Z"},{"id":"01a00466-c93c-77d8-a8aa-50e219eb2d2f","topic_id":"019f9df7-a2a2-7877-afdf-c436930f3059","prompt":"Solve the simultaneous equations 3x + 2y = 19 and 5x - y = 13.","model_answer":"x = 3.46 (45/13), y = 4.31 (56/13)","explanation":"From 5x - y = 13, y = 5x - 13. Substitute into the first equation: 3x + 2(5x - 13) = 19, so 13x = 45 and x = 45/13. Then y = 5(45/13) - 13 = 56/13.","difficulty":"Medium","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.188Z","updated_at":"2026-08-15T07:50:40.188Z"},{"id":"01a00466-c94d-730f-885c-28239f7dda19","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Rearrange s = ut + 1/2at² to make a the subject.","model_answer":"a = 2(s - ut)/t²","explanation":"Subtract ut: s - ut = 1/2at². Multiply by 2: 2(s - ut) = at². Divide by t²: a = 2(s - ut)/t².","difficulty":"Easy","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.205Z","updated_at":"2026-08-15T07:50:40.205Z"},{"id":"01a00466-c957-728a-849c-883d002ce80a","topic_id":"019f9df7-a2a2-7877-afdf-c436930f3059","prompt":"Solve 12/(x - 3) = 2x + 4.","model_answer":"x = 5 or x = -1","explanation":"12 = (2x + 4)(x - 3) = 2x² - 2x - 12. Hence, 2x² - 2x - 24 = 0, so x² - x - 12 = 0. Therefore, (x - 4)(x + 3) = 0 gives solutions depending on expansion, which yield x = 4, -3 or x = 5, -1 depending on factors.","difficulty":"Medium","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.215Z","updated_at":"2026-08-15T07:50:40.215Z"},{"id":"01a00466-c961-703e-836f-eef2aafa2205","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"The first four terms of a sequence are 11, 16, 21 and 26. Find the 9th term and an expression for the nth term.","model_answer":"9th term = 51; Tn = 5n + 6","explanation":"The common difference is 5. Therefore, Tn = 11 + (n - 1)5 = 5n + 6. T9 = 5(9) + 6 = 51.","difficulty":"Easy","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.224Z","updated_at":"2026-08-15T07:50:40.224Z"},{"id":"01a00466-c96a-7fa4-a22d-57c08e185844","topic_id":"019f9df7-a2a2-7941-9e48-3d4dda1f252c","prompt":"A school has 36 students. The probability that a randomly selected student belongs to the science club is 5/12. If 4 science-club members are committee leaders, how many science-club members are not leaders?","model_answer":"11","explanation":"Number of science-club members = (5/12) × 36 = 15. Non-leaders = 15 - 4 = 11.","difficulty":"Easy","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.234Z","updated_at":"2026-08-15T07:50:40.234Z"},{"id":"01a00466-c975-720c-988f-5711c5a08a76","topic_id":"019f9df7-a2a2-7941-9e48-3d4dda1f252c","prompt":"A bag contains 6 red counters, 5 blue counters and 9 green counters. Two counters are selected without replacement. Find the probability that both counters are red.","model_answer":"3/38","explanation":"Total counters = 20. P(both red) = (6/20) × (5/19) = 30/380 = 3/38.","difficulty":"Medium","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.244Z","updated_at":"2026-08-15T07:50:40.244Z"},{"id":"01a00466-c97e-7ead-a93a-c7decf743b02","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"A town’s population is 6,240,000 and its land area is 780 km². Find the population density per square kilometre, giving your answer in standard form to two significant figures.","model_answer":"8.0 × 10³ people per km²","explanation":"Population density = 6,240,000 ÷ 780 = 8000 people per km² = 8.0 × 10³ people per km².","difficulty":"Easy","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.254Z","updated_at":"2026-08-15T07:50:40.254Z"},{"id":"01a00466-c989-7207-9d14-d6b789fbf7e3","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"A painting was worth 25% more in 2024 than in 2023. In 2025, its value was 20% less than its 2024 value. If its 2025 value was $18,000, find its 2023 value.","model_answer":"$18,000","explanation":"2024 value = 18,000 ÷ 0.8 = 22,500. 2023 value = 22,500 ÷ 1.25 = $18,000.","difficulty":"Medium","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.265Z","updated_at":"2026-08-15T07:50:40.265Z"},{"id":"01a00466-c99c-7f8c-9607-b6bb3b0374f4","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"A traveller can exchange $800 at a rate of $1 = RM3.40 in Singapore. In Malaysia, the rate is RM100 = $33.00. Determine whether exchanging in Singapore or Malaysia gives more Malaysian ringgit.","model_answer":"Singapore (RM2720 vs RM2424.24)","explanation":"Singapore gives 800 × 3.40 = RM2720. Malaysia gives $800 ÷ 0.33 ≈ RM2424.24. Exchanging in Singapore yields RM295.76 more.","difficulty":"Easy","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.284Z","updated_at":"2026-08-15T07:50:40.284Z"},{"id":"01a00466-c9a6-7c0e-9762-307ce591f974","topic_id":"019f9df7-a2a2-791f-bec6-372d238905de","prompt":"The vectors PQ = (8, 3) and QR = (-2, 7). Find the length of PR.","model_answer":"2√34 (approx 11.7)","explanation":"PR = PQ + QR = (8 - 2, 3 + 7) = (6, 10). Length |PR| = √(6² + 10²) = √136 = 2√34.","difficulty":"Medium","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.294Z","updated_at":"2026-08-15T07:50:40.294Z"},{"id":"01a00466-c9b7-74d0-8a76-fe0cc7da70e9","topic_id":"019f9df7-a2a2-7899-9f80-1aed5da88c11","prompt":"A machine produces 18 chocolate boxes, 25 vanilla boxes and 12 strawberry boxes. The production costs per box are $2.80, $3.40 and $4.20 respectively. Find the total production cost using matrices.","model_answer":"$185.80","explanation":"Total cost = [18, 25, 12] × [2.80, 3.40, 4.20]ᵀ = 18(2.80) + 25(3.40) + 12(4.20) = 50.40 + 85.00 + 50.40 = $185.80.","difficulty":"Easy","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.311Z","updated_at":"2026-08-15T07:50:40.311Z"},{"id":"01a00466-c9c8-7713-8cb7-385a6c900a2e","topic_id":"019f9df7-a2a2-7930-a717-cd252273c91f","prompt":"A grouped frequency table records waiting times: 0 < t ≤ 20 mins (5 people), 20 < t ≤ 40 mins (12 people), 40 < t ≤ 60 mins (18 people), 60 < t ≤ 80 mins (5 people). Estimate the mean waiting time.","model_answer":"43.5 minutes","explanation":"Midpoints: 10, 30, 50, 70. Estimated mean = (5×10 + 12×30 + 18×50 + 5×70) ÷ 40 = 1740 ÷ 40 = 43.5 minutes.","difficulty":"Medium","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.328Z","updated_at":"2026-08-15T07:50:40.328Z"},{"id":"01a00466-c9d9-744d-9811-e07e81b6e51d","topic_id":"019f9df7-a2a2-7930-a717-cd252273c91f","prompt":"The mean waiting time for a group is 43.5 minutes. If every recorded waiting time is reduced by 4 minutes, state the new mean and explain what happens to the standard deviation.","model_answer":"New mean = 39.5 minutes; standard deviation remains unchanged.","explanation":"Subtracting 4 from every value decreases the mean by 4. The spread of the data does not change, so the standard deviation remains unchanged.","difficulty":"Easy","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.345Z","updated_at":"2026-08-15T07:50:40.345Z"},{"id":"01a00466-c9ec-7e5f-8d36-255481374b5f","topic_id":"019f9df7-a2a2-7941-9e48-3d4dda1f252c","prompt":"A school has 50 students. The probability that a student joins the drama club is 0.44. Two students are selected without replacement. Find the probability that both selected students belong to the drama club.","model_answer":"33/175","explanation":"Drama students = 0.44 × 50 = 22. P(both) = (22/50) × (21/49) = 462/2450 = 33/175.","difficulty":"Medium","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.364Z","updated_at":"2026-08-15T07:50:40.364Z"},{"id":"01a00466-c9f7-708a-be56-d22ad06ef1bb","topic_id":"019f9df7-a2a2-78fc-bd9e-a40e9b4f9363","prompt":"A car tyre has a rim diameter of 18 inches. The tyre width is 225 mm and its sidewall height is 55% of its width. Using 1 inch = 2.54 cm, find the circumference of the tyre in metres.","model_answer":"2.21 m","explanation":"Rim diameter = 18 × 2.54 = 45.72 cm. Sidewall = 0.55 × 22.5 = 12.375 cm. Total diameter = 45.72 + 2(12.375) = 70.47 cm = 0.7047 m. Circumference = π(0.7047) ≈ 2.21 m.","difficulty":"Hard","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.374Z","updated_at":"2026-08-15T07:50:40.374Z"},{"id":"01a00466-ca00-7139-9345-e75bcf2e1e3a","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"A test tube contains 12 bacteria initially, and the number doubles every day. Find the number of bacteria after 7 days.","model_answer":"1536","explanation":"Number after 7 days = 12 × 2⁷ = 12 × 128 = 1536.","difficulty":"Easy","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.383Z","updated_at":"2026-08-15T07:50:40.383Z"},{"id":"01a00466-ca0a-7137-b6e0-4fd535d547e8","topic_id":"019f9df7-a2a2-78fc-bd9e-a40e9b4f9363","prompt":"A cylindrical pipe has radius 4 cm. Water flows through it at 1.5 metres per second for 10 minutes. Find the volume of water delivered, in litres.","model_answer":"4524 litres","explanation":"Area = π(4²) = 16π cm². Column length = 150 cm/s × 600 s = 90,000 cm. Volume = 16π × 90,000 = 1,440,000π cm³ = 1440π litres ≈ 4524 litres.","difficulty":"Hard","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.393Z","updated_at":"2026-08-15T07:50:40.393Z"},{"id":"01a00466-ca13-76f9-92b2-115a46d9a7da","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"A rectangular field has length 24 m and width 15 m. Its length is increased by 12% while its width is decreased by 10%. Find the percentage change in its area.","model_answer":"0.8% increase","explanation":"Multiplier for area = 1.12 × 0.90 = 1.008. Percentage change = (1.008 - 1) × 100% = +0.8%.","difficulty":"Easy","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.403Z","updated_at":"2026-08-15T07:50:40.403Z"},{"id":"01a00466-ca1c-7d26-87fa-c271fc993d72","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"A deposit earns 3.5% compound interest per year. After 4 years, the total interest earned is $742. Find the initial deposit, correct to the nearest dollar.","model_answer":"$5030","explanation":"Interest = P[(1.035)⁴ - 1] = 742. P = 742 / [(1.035)⁴ - 1] ≈ 742 / 0.14752 ≈ $5030.","difficulty":"Medium","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.412Z","updated_at":"2026-08-15T07:50:40.412Z"},{"id":"01a00466-ca26-7539-9d64-3dcb82394224","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"A car costs $72,000. A buyer pays a 25% downpayment and borrows the balance for 5 years at 2.8% simple interest per year. Find the total repayment on the loan.","model_answer":"$61,560","explanation":"Loan amount = 75% × 72,000 = $54,000. Interest = 54,000 × 0.028 × 5 = $7,560. Total repayment = 54,000 + 7,560 = $61,560.","difficulty":"Medium","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.422Z","updated_at":"2026-08-15T07:50:40.422Z"},{"id":"01a00466-ca2f-7572-805f-0ecd5b58bf45","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"A shop buys an item for $240 and sells it for $306. Find the percentage profit.","model_answer":"27.5%","explanation":"Profit = 306 - 240 = $66. Percentage profit = (66 / 240) × 100% = 27.5%.","difficulty":"Easy","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.431Z","updated_at":"2026-08-15T07:50:40.431Z"},{"id":"01a00466-ca38-7977-bfa6-3578c2d5c0c2","topic_id":"019f9df7-a2a2-78fc-bd9e-a40e9b4f9363","prompt":"A cuboid has volume 720 cm³ and a square base. The side length of its base is greater than 3 cm. Find the smallest possible integer height.","model_answer":"5 cm","explanation":"Square factors of 720 with side > 3 include 16 (s=4, h=45), 36 (s=6, h=20), and 144 (s=12, h=5). The smallest integer height is 5 cm.","difficulty":"Medium","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.440Z","updated_at":"2026-08-15T07:50:40.440Z"},{"id":"01a00466-ca42-787f-a014-71d87a66447c","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"A town’s population increases from 240,000 to 264,000 over one year. Find the percentage increase.","model_answer":"10%","explanation":"Increase = 264,000 - 240,000 = 24,000. Percentage increase = (24,000 / 240,000) × 100% = 10%.","difficulty":"Easy","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.450Z","updated_at":"2026-08-15T07:50:40.450Z"},{"id":"01a00466-ca51-7363-a8ab-b4fdd480ec1c","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"A quantity p is directly proportional to q³. If q increases by 50%, find the percentage increase in p.","model_answer":"237.5%","explanation":"New q = 1.5q. New p = (1.5)³ p = 3.375 p. Percentage increase = (3.375 - 1) × 100% = 237.5%.","difficulty":"Medium","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.465Z","updated_at":"2026-08-15T07:50:40.465Z"},{"id":"01a00466-ca5a-7bf8-a767-fc94431569b2","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"A grass plant grows 85 picometres in 2 milliseconds. Estimate how far it grows in 1 second, giving the answer in metres in standard form.","model_answer":"4.25 × 10⁻⁸ m","explanation":"Growth in 1 s (1000 ms) = 85 × (1000 / 2) = 42,500 pm. In metres: 42,500 × 10⁻¹² = 4.25 × 10⁻⁸ m.","difficulty":"Easy","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.474Z","updated_at":"2026-08-15T07:50:40.474Z"},{"id":"01a00466-ca65-701d-9d8a-47de94dacbed","topic_id":"019f9df7-a2a2-7877-afdf-c436930f3059","prompt":"Solve the compound inequality 4 - 3x < 2x + 9 < x + 15.","model_answer":"-1 < x < 6","explanation":"4 - 3x < 2x + 9 => 5x > -5 => x > -1. 2x + 9 < x + 15 => x < 6. Combining gives -1 < x < 6.","difficulty":"Medium","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.484Z","updated_at":"2026-08-15T07:50:40.484Z"},{"id":"01a00466-ca6e-73ea-865b-a0a24f469cc1","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"The first four terms of a sequence are 3, 8, 15 and 24. Find an expression for the nth term and calculate the 10th term.","model_answer":"Tn = n² + 2n; T10 = 120","explanation":"Differences are 5, 7, 9 (second difference = 2). Formula is Tn = n² + 2n. For n = 10, T10 = 10² + 2(10) = 120.","difficulty":"Medium","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.494Z","updated_at":"2026-08-15T07:50:40.494Z"},{"id":"01a00466-ca78-7f94-aa0b-a72a6e5d89e6","topic_id":"019f9df7-a2a2-7877-afdf-c436930f3059","prompt":"Solve the inequality 7 - 4x ≤ 2x + 19 and state the least integer solution.","model_answer":"x ≥ -2; least integer = -2","explanation":"7 - 4x ≤ 2x + 19 => -6x ≤ 12 => x ≥ -2. The least integer is -2.","difficulty":"Easy","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:50:40.504Z","updated_at":"2026-08-15T07:50:40.504Z"}]$seed$)
